use rand::SeedableRng;
use rand_chacha::ChaCha8Rng;
use rand_distr::{Normal, Distribution};
use std::fs::File;
use std::io::Write;
fn main() {
    let mut rng = ChaCha8Rng::seed_from_u64(42);
    let normal = Normal::new(500.0, 20.0).unwrap();
    let (mut a, mut b) = (1_000_000.0f64, 0.0f64);
    let (la, lb, dt) = (0.1f64, 0.05f64, 1.0f64);
    let mut hist = [0u64; 40];
    for _ in 0..60 {
        let da = la * a * dt;
        let db = lb * b * dt;
        let n = (db * 0.1).floor() as i64;
        for _ in 0..n {
            let e: f64 = normal.sample(&mut rng);
            if e >= 400.0 && e < 600.0 {
                let idx = ((e - 400.0) / 5.0).floor() as usize;
                hist[idx] += 1;
            }
        }
        a -= da; b += da - db;
    }
    let mut f = File::create("/home/user/spectrum.csv").unwrap();
    for i in 0..40 { writeln!(f, "{},{}", 400 + i * 5, hist[i]).unwrap(); }
}
RS
